    {
        public string Source;
        public string Target;
        public string EdgeType;
    }

    public sealed class EgoGraphResult
    {
        public List<string> NodeIds = new List<string>();
        public List<GraphEdge> Edges = new List<GraphEdge>();
        public bool Truncated;
    }

    public static class CsvExporter
    {
        public static void Export(string[] ndjsonFiles, string[] fields, string outputPath)
        {
            using (var writer = new StreamWriter(outputPath, false, new UTF8Encoding(false)))
            {
                writer.WriteLine(string.Join(",", fields));
                var sb = new StringBuilder(256);
                foreach (var file in ndjsonFiles)
                {
                    foreach (string line in NdjsonReader.Lines(file))
                    {

                            if (line.Length == 0) continue;
                            sb.Clear();
                            for (int i = 0; i < fields.Length; i++)
                            {
                                if (i > 0) sb.Append(',');
                                string v = JsonRecordReader.ExtractField(line, fields[i]);
                                if (v != null)
                                {
                                    sb.Append('"');
                                    if (v.Length > 0 && "=+-@\t\r\n".IndexOf(v[0]) >= 0) sb.Append('\'');
                                    sb.Append(v.Replace("\"", "\"\""));
                                    sb.Append('"');
                                }
                            }
                            writer.WriteLine(sb.ToString());
                    }
                }
            }
        }
    }
}








namespace BH.Native
{
    // Windows supplies SQLite. Keep a single writer transaction and a bounded
    // page cache; graph queries seek to a node's incoming edges on disk.
    public sealed partial class GraphIndex : IDisposable
    {
        private const string Library = "winsqlite3.dll";
        private const int Row = 100;
        private const int Done = 101;
        private IntPtr db;

        [DllImport(Library, CallingConvention = CallingConvention.Cdecl)]
        private static extern int sqlite3_open_v2(byte[] path, out IntPtr handle, int flags, IntPtr vfs);
        [DllImport(Library, CallingConvention = CallingConvention.Cdecl)]
        private static extern int sqlite3_close(IntPtr handle);
        [DllImport(Library, CallingConvention = CallingConvention.Cdecl)]
        private static extern IntPtr sqlite3_errmsg16(IntPtr handle);
        [DllImport(Library, CallingConvention = CallingConvention.Cdecl)]
        private static extern int sqlite3_exec(IntPtr handle, byte[] sql, IntPtr callback, IntPtr argument, IntPtr error);
        [DllImport(Library, CallingConvention = CallingConvention.Cdecl)]
        private static extern int sqlite3_prepare_v2(IntPtr handle, byte[] sql, int length, out IntPtr statement, IntPtr tail);
        [DllImport(Library, CallingConvention = CallingConvention.Cdecl)]
        private static extern int sqlite3_step(IntPtr statement);
        [DllImport(Library, CallingConvention = CallingConvention.Cdecl)]
        private static extern int sqlite3_reset(IntPtr statement);
        [DllImport(Library, CallingConvention = CallingConvention.Cdecl)]
        private static extern int sqlite3_finalize(IntPtr statement);
        [DllImport(Library, CallingConvention = CallingConvention.Cdecl, CharSet = CharSet.Unicode, ExactSpelling = true)]
        private static extern int sqlite3_bind_text16(IntPtr statement, int index, string value, int bytes, IntPtr destructor);
        [DllImport(Library, CallingConvention = CallingConvention.Cdecl)]
        private static extern IntPtr sqlite3_column_text16(IntPtr statement, int column);
        [DllImport(Library, CallingConvention = CallingConvention.Cdecl)]
        private static extern int sqlite3_column_bytes16(IntPtr statement, int column);
        [DllImport(Library, CallingConvention = CallingConvention.Cdecl)]
        private static extern int sqlite3_bind_blob(IntPtr statement, int index, byte[] bytes, int count, IntPtr destructor);
        [DllImport(Library, CallingConvention = CallingConvention.Cdecl)]
        private static extern int sqlite3_column_type(IntPtr statement, int column);
        [DllImport(Library, CallingConvention = CallingConvention.Cdecl)]
        private static extern IntPtr sqlite3_column_blob(IntPtr statement, int column);
        [DllImport(Library, CallingConvention = CallingConvention.Cdecl)]
        private static extern int sqlite3_column_bytes(IntPtr statement, int column);

        private static byte[] Utf8(string value) { return Encoding.UTF8.GetBytes(value + "\0"); }

        private void Check(int status)
        {
            if (status != 0 && status != Row && status != Done)
                throw new IOException("SQLite error " + status + ": " + Marshal.PtrToStringUni(sqlite3_errmsg16(db)));
        }

        public GraphIndex(string path, bool create)
            : this(path, create, false) { }

        public GraphIndex(string path, bool create, bool writable)
        {
            try
            {
                Check(sqlite3_open_v2(Utf8(path), out db, create ? 6 : writable ? 2 : 1, IntPtr.Zero));
                Execute("PRAGMA cache_size=-65536; PRAGMA temp_store=FILE;");
                if (create)
                {
                    Execute(@"CREATE TABLE nodes (id TEXT COLLATE NOCASE PRIMARY KEY, name TEXT, kind TEXT, disabled TEXT, record TEXT, security_enabled TEXT) WITHOUT ROWID;
                              CREATE TABLE dns (dn TEXT COLLATE NOCASE PRIMARY KEY, id TEXT) WITHOUT ROWID;
                              CREATE TABLE external (id TEXT COLLATE NOCASE PRIMARY KEY, name TEXT, kind TEXT) WITHOUT ROWID;
                              CREATE TABLE edges (target TEXT COLLATE NOCASE, bucket TEXT, source TEXT COLLATE NOCASE, type TEXT,
                                  target_dn INTEGER, source_dn INTEGER, evidence TEXT,
                                  PRIMARY KEY (target, bucket, source, type)) WITHOUT ROWID;");
                }
            }
            catch
            {
                Dispose();
                throw;
            }
        }

        public void Dispose()
        {
            if (db == IntPtr.Zero) return;
            sqlite3_close(db);
            db = IntPtr.Zero;
        }

        private void Execute(string sql)
        {
            Check(sqlite3_exec(db, Utf8(sql), IntPtr.Zero, IntPtr.Zero, IntPtr.Zero));
        }

        private sealed class Statement : IDisposable
        {
            private readonly GraphIndex owner;
            internal IntPtr handle;

            public Statement(GraphIndex owner, string sql)
            {
                this.owner = owner;
                owner.Check(sqlite3_prepare_v2(owner.db, Utf8(sql), -1, out handle, IntPtr.Zero));
            }

            public void Bind(int index, string value)
            {
                owner.Check(sqlite3_bind_text16(handle, index, value, value == null ? 0 : value.Length * 2, new IntPtr(-1)));
            }

            public bool Read()
            {
                int status = sqlite3_step(handle);
                owner.Check(status);
                return status == Row;
            }

            public void Reset() { owner.Check(sqlite3_reset(handle)); }

            public void BindRecord(int index, string record)
            {
                if (record == null || record.Length <= 512) { Bind(index, record); return; }
                byte[] bytes = Encoding.UTF8.GetBytes(record);
                using (var output = new MemoryStream())
                {
                    using (var gzip = new GZipStream(output, CompressionLevel.Fastest, true)) gzip.Write(bytes, 0, bytes.Length);
                    byte[] compressed = output.ToArray();
                    if (compressed.Length >= bytes.Length) { Bind(index, record); return; }
                    owner.Check(sqlite3_bind_blob(handle, index, compressed, compressed.Length, new IntPtr(-1)));
                }
            }

            public string Record(int column)
            {
                if (sqlite3_column_type(handle, column) != 4) return Text(column);
                int length = sqlite3_column_bytes(handle, column);
                var bytes = new byte[length];
                Marshal.Copy(sqlite3_column_blob(handle, column), bytes, 0, length);
                using (var compressed = new MemoryStream(bytes))
                using (var gzip = new GZipStream(compressed, CompressionMode.Decompress))
                using (var text = new StreamReader(gzip, Encoding.UTF8)) return text.ReadToEnd();
            }

            public string Text(int column)
            {
                IntPtr value = sqlite3_column_text16(handle, column);
                return value == IntPtr.Zero ? null : Marshal.PtrToStringUni(value, sqlite3_column_bytes16(handle, column) / 2);
            }

            public void Dispose() { sqlite3_finalize(handle); }
        }

        public void Import(string[] paths, string[] kinds, string[] edgePaths, string[] buckets, string[] externalPaths, bool retainNodes)
        {
            if (paths.Length != kinds.Length || edgePaths.Length != buckets.Length)
                throw new ArgumentException("Every dataset file requires a type.");

            Execute("BEGIN IMMEDIATE");
            try
            {
                using (var node = new Statement(this, "INSERT OR IGNORE INTO nodes VALUES (?1,?2,?3,?4,?5,?6)"))
                using (var alias = new Statement(this, "INSERT OR IGNORE INTO dns VALUES (?1,?2)"))
                {
                    for (int i = 0; i < paths.Length; i++)
                    {
                        foreach (string line in NdjsonReader.Lines(paths[i]))
                        {
                            if (line.Length == 0) continue;
                            string id = Required(line, "Id", paths[i]);
                            string dn = JsonRecordReader.ExtractField(line, "Dn");
                            node.Bind(1, id);
                            node.Bind(2, JsonRecordReader.ExtractField(line, "Name"));
                            node.Bind(3, kinds[i]);
                            node.Bind(4, JsonRecordReader.ExtractField(line, "Disabled"));
                            node.BindRecord(5, retainNodes ? line : null);
                            node.Bind(6, kinds[i] == "groups" ? JsonRecordReader.ExtractField(line, "SecurityEnabled") : null);
                            node.Read();
                            node.Reset();
                            if (!string.IsNullOrEmpty(dn)) WriteAlias(alias, dn.ToUpperInvariant(), id);
                            string template = JsonRecordReader.ExtractField(line, "TemplateAlias");
                            if (template != null) WriteAlias(alias, "TEMPLATE:" + template.ToUpperInvariant(), id);
                            foreach (string spn in JsonRecordReader.StringArray(line, "Spns"))
                                WriteAlias(alias, "SPN:" + spn.ToUpperInvariant(), id);
                        }
                    }
                }
                using (var directEdge = new Statement(this, "INSERT OR IGNORE INTO edges VALUES (?1,?2,?3,?4,0,0,?7)"))
                using (var dnEdge = new Statement(this, @"INSERT OR IGNORE INTO edges
                    SELECT COALESCE(t.id,?1),?2,COALESCE(s.id,?3),?4,
                           ?5 IS NOT NULL AND t.id IS NULL, ?6 IS NOT NULL AND s.id IS NULL, ?7
                    FROM (SELECT 1) LEFT JOIN dns t ON t.dn=?5
                                    LEFT JOIN dns s ON s.dn=?6"))
                {
                    for (int i = 0; i < edgePaths.Length; i++)
                    {
                        foreach (string line in NdjsonReader.Lines(edgePaths[i]))
                        {
                            if (line.Length == 0) continue;
                            string target = Required(line, "Target", edgePaths[i]);
                            string source = Required(line, "Source", edgePaths[i]);
                            bool targetIsDn = JsonRecordReader.ExtractField(line, "TargetIsDn") == "true";
                            bool sourceIsDn = JsonRecordReader.ExtractField(line, "SourceIsDn") == "true";
                            var edge = targetIsDn || sourceIsDn ? dnEdge : directEdge;
                            edge.Bind(1, target);
                            edge.Bind(2, buckets[i]);
                            edge.Bind(3, source);
                            edge.Bind(4, Required(line, "EdgeType", edgePaths[i]));
                            edge.Bind(7, buckets[i] == "observed" ? line : null);
                            if (edge == dnEdge)
                            {
                                edge.Bind(5, targetIsDn ? target.ToUpperInvariant() : null);
                                edge.Bind(6, sourceIsDn ? source.ToUpperInvariant() : null);
                            }
                            edge.Read();
                            edge.Reset();
                        }
                    }
                }
                using (var external = new Statement(this, "INSERT OR IGNORE INTO external VALUES (?1,?2,?3)"))
                {
                    foreach (string path in externalPaths)
                    {
                        foreach (string line in NdjsonReader.Lines(path))
                        {
                            if (line.Length == 0) continue;
                            external.Bind(1, Required(line, "Id", path));
                            external.Bind(2, JsonRecordReader.ExtractField(line, "Name"));
                            external.Bind(3, JsonRecordReader.ExtractField(line, "Type"));
                            external.Read();
                            external.Reset();
                        }
                    }
                }
                Execute("COMMIT");
            }
            catch
            {
                Execute("ROLLBACK");
                throw;
            }
        }

        private static string Required(string line, string field, string path)
        {
            string value = JsonRecordReader.ExtractField(line, field);
            if (string.IsNullOrEmpty(value)) throw new InvalidDataException("Missing " + field + " in " + path);
            return value;
        }

        private static void WriteAlias(Statement statement, string name, string id)
        {
            statement.Bind(1, name);
            statement.Bind(2, id);
            statement.Read();
            statement.Reset();
        }

        private List<string[]> Query(string sql, int columns)
        {
            var result = new List<string[]>();
            using (var statement = new Statement(this, sql))
            {
                while (statement.Read())
                {
                    var row = new string[columns];
                    for (int i = 0; i < columns; i++) row[i] = statement.Text(i);
                    result.Add(row);
                }
            }
            return result;
        }

        public List<string[]> NodeCounts() { return Query("SELECT kind,count(*) FROM nodes GROUP BY kind", 2); }
        public List<string[]> EdgeCounts() { return Query("SELECT bucket,count(*) FROM edges GROUP BY bucket", 2); }
        public List<string[]> UnresolvedCounts() { return Query("SELECT bucket,count(*) FROM edges WHERE target_dn OR source_dn GROUP BY bucket", 2); }
        public List<string[]> UserCounts() { return Query("SELECT disabled,count(*) FROM nodes WHERE kind='users' GROUP BY disabled", 2); }

        // A bounded evidence sample, including relationships outside the graph preview.
        // Each bucket stops at its limit without sorting the full edge table.
        public List<string[]> ReviewRelationships()
        {
            return ReviewRelationships(new[] { "acl", "access", "observed" });
        }

        public List<string[]> ReviewRelationships(string[] buckets)
        {
            var result = new List<string[]>();
            foreach (string bucket in buckets)
            {
                if (bucket != "acl" && bucket != "access" && bucket != "observed")
                    throw new ArgumentException("Invalid review relationship bucket.");
                result.AddRange(Query(@"SELECT e.source,e.target,e.type,s.name,t.name,t.kind
                    FROM edges e LEFT JOIN nodes s ON s.id=e.source LEFT JOIN nodes t ON t.id=e.target
                    WHERE e.bucket='" + bucket + "' LIMIT 40", 6));
            }
            return result;
        }

        public long WriteMerged(string directory, string[] nodeKinds, string[] edgeBuckets)
        {
            return WriteMerged(directory, nodeKinds, edgeBuckets, false);
        }

        public long WriteMerged(string directory, string[] nodeKinds, string[] edgeBuckets, bool compress)
        {
            string suffix = compress ? ".ndjson.gz" : ".ndjson";
            using (var nodes = new Statement(this, "SELECT record FROM nodes WHERE kind=?1"))
            {
                foreach (string kind in nodeKinds)
                {
                    using (var writer = new NdjsonWriter(Path.Combine(directory, "nodes_" + kind + suffix), false))
                    {
                        nodes.Bind(1, kind);
                        while (nodes.Read()) writer.WriteLine(nodes.Record(0));
                        nodes.Reset();
                    }
                }
            }
            var json = new JsonRecordWriter();
            using (var edges = new Statement(this, "SELECT source,target,type,source_dn,target_dn,evidence FROM edges WHERE bucket=?1"))
            {
                foreach (string bucket in edgeBuckets)
                {
                    using (var writer = new NdjsonWriter(Path.Combine(directory, "edges_" + bucket + suffix), false))
                    {
                        edges.Bind(1, bucket);
                        while (edges.Read())
                        {
                            string evidence = edges.Text(5);
                            if (evidence != null)
                            {
                                writer.WriteLine(JsonRecordReader.NormalizeEdge(evidence, edges.Text(0), edges.Text(1),
                                    edges.Text(3) == "1", edges.Text(4) == "1"));
                                continue;
                            }
                            json.Begin().Prop("Source", edges.Text(0)).Prop("Target", edges.Text(1)).Prop("EdgeType", edges.Text(2));
                            if (edges.Text(3) == "1") json.Prop("SourceIsDn", true);
                            if (edges.Text(4) == "1") json.Prop("TargetIsDn", true);
                            writer.WriteLine(json.End());
                        }
                        edges.Reset();
                    }
                }
            }
            long count = 0;
            using (var external = new Statement(this, "SELECT id,name,kind FROM external"))
            using (var writer = new NdjsonWriter(Path.Combine(directory, "principals_external" + suffix), false))
            {
                while (external.Read())
                {
                    writer.WriteLine(json.Begin().Prop("Id", external.Text(0)).Prop("Name", external.Text(1)).Prop("Type", external.Text(2)).End());
                    count++;
                }
            }
            return count;
        }
        public List<string[]> TopAclHolders()
        {
            return Query(@"SELECT a.source,n.name,n.kind,a.rights FROM
                           (SELECT source,count(*) rights FROM edges WHERE bucket='acl' GROUP BY source
                            ORDER BY rights DESC,source LIMIT 50) a LEFT JOIN nodes n ON n.id=a.source
                           ORDER BY a.rights DESC,a.source", 4);
        }
        public List<string[]> Groups()
        {
            return Query(@"SELECT id,name FROM nodes WHERE kind='groups' AND security_enabled IS NOT 'false' AND
                           ((id GLOB 'S-1-5-21-*' AND
                             (id LIKE '%-512' OR id LIKE '%-516' OR id LIKE '%-518' OR id LIKE '%-519' OR
                              id LIKE '%-521' OR id LIKE '%-526' OR id LIKE '%-527')) OR
                            id LIKE '%S-1-5-32-544' OR id LIKE '%S-1-5-32-548' OR id LIKE '%S-1-5-32-549' OR
                            id LIKE '%S-1-5-32-550' OR id LIKE '%S-1-5-32-551')", 2);
        }
        public List<string[]> SearchSample(int limit)
        {
            return Query("SELECT id,name,kind FROM nodes WHERE name IS NOT NULL LIMIT " + limit, 3);
        }

        public string[] Node(string id)
        {
            using (var statement = new Statement(this, "SELECT name,kind FROM nodes WHERE id=?1 UNION ALL SELECT name,kind FROM external WHERE id=?1 LIMIT 1"))
            {
                statement.Bind(1, id);
                return statement.Read() ? new[] { statement.Text(0), statement.Text(1) } : null;
            }
        }

        public string NodeRecord(string id)
        {
            using (var statement = new Statement(this, "SELECT record FROM nodes WHERE id=?1"))
            {
                statement.Bind(1, id);
                return statement.Read() ? statement.Record(0) : null;
            }
        }

        public List<string[]> Search(string name)
        {
            var result = new List<string[]>();
            using (var statement = new Statement(this, "SELECT id,name,kind FROM nodes WHERE instr(lower(name),lower(?1))>0 LIMIT 100"))
            {
                statement.Bind(1, name);
                while (statement.Read()) result.Add(new[] { statement.Text(0), statement.Text(1), statement.Text(2) });
            }
            return result;
        }

        public EgoGraphResult Neighborhood(string[] seeds, int depthCap, int nodeCap, int edgeCap)
        {
            var result = new EgoGraphResult();
            var visited = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            var pending = new Queue<KeyValuePair<string, int>>();
            foreach (string seed in seeds)
            {
                if (visited.Count == nodeCap) { result.Truncated = true; break; }
                if (visited.Add(seed)) pending.Enqueue(new KeyValuePair<string, int>(seed, 0));
            }
            using (var incoming = Incoming())
            {
                while (pending.Count > 0 && !result.Truncated)
                {
                    var current = pending.Dequeue();
                    if (current.Value >= depthCap) continue;
                    incoming.Bind(1, current.Key);
                    while (incoming.Read())
                    {
                        var edge = ReadEdge(incoming, current.Key);
                        if (result.Edges.Count == edgeCap || (visited.Count == nodeCap && !visited.Contains(edge.Source)))
                        {
                            result.Truncated = true;
                            break;
                        }
                        result.Edges.Add(edge);
                        if (visited.Add(edge.Source)) pending.Enqueue(new KeyValuePair<string, int>(edge.Source, current.Value + 1));
                    }
                    incoming.Reset();
                }
            }
            result.NodeIds.AddRange(visited);
            return result;
        }

        public EgoGraphResult ShortestPath(string source, string target, int maxVisited)
        {
            return ShortestPath(source, target, maxVisited, null);
        }

        public EgoGraphResult ShortestPath(string source, string target, int maxVisited, string[] allowedTypes)
        {
            var result = new EgoGraphResult();
            var allowed = allowedTypes == null ? null : new HashSet<string>(allowedTypes, StringComparer.OrdinalIgnoreCase);
            var next = new Dictionary<string, GraphEdge>(StringComparer.OrdinalIgnoreCase);
            var pending = new Queue<string>();
            next.Add(target, new GraphEdge());
            pending.Enqueue(target);
            using (var incoming = Incoming())
            {
                while (pending.Count > 0 && !next.ContainsKey(source))
                {
                    string current = pending.Dequeue();
                    incoming.Bind(1, current);
                    while (incoming.Read())
                    {
                        var edge = ReadEdge(incoming, current);
                        if (allowed != null && !allowed.Contains(edge.EdgeType)) continue;
                        if (next.ContainsKey(edge.Source)) continue;
                        if (next.Count == maxVisited)
                        {
                            result.Truncated = true;
                            return result;
                        }
                        next.Add(edge.Source, edge);
                        pending.Enqueue(edge.Source);
                        if (StringComparer.OrdinalIgnoreCase.Equals(edge.Source, source)) break;
                    }
                    incoming.Reset();
                }
            }
            if (!next.ContainsKey(source)) return result;
            string id = source;
            result.NodeIds.Add(id);
            while (!StringComparer.OrdinalIgnoreCase.Equals(id, target))
            {
                GraphEdge edge = next[id];
                result.Edges.Add(edge);
                id = edge.Target;
                result.NodeIds.Add(id);
            }
            return result;
        }

        private Statement Incoming()
        {
            return new Statement(this, @"SELECT source,type FROM edges
                WHERE target=?1 AND bucket IN ('acl','memberof','access') AND source<>target AND source_dn=0 AND target_dn=0
                AND (bucket<>'memberof' OR NOT EXISTS (
                    SELECT 1 FROM nodes WHERE id=?1 AND security_enabled='false'))");
        }

        private static GraphEdge ReadEdge(Statement row, string target)
        {
            return new GraphEdge { Source = row.Text(0), Target = target, EdgeType = row.Text(1) };
        }
    }
}







namespace BH.Native
{
    public sealed class ExposureFinding
    {
        public string Id;
        public string Source;
        public string Target;
        public List<GraphEdge> Steps = new List<GraphEdge>();
        public int Score;
        public string Priority;
        public long DirectMembers;
        public bool MissingObjects;
        public List<string> Reasons = new List<string>();
        public long Sequence;
        public int HopCount;
        public bool PathLimited;
        public string NextPathId;
    }
    public sealed class ExposureAnalysis
    {
        public List<ExposureFinding> Findings = new List<ExposureFinding>();
        public int Visited;
        public bool Truncated;
        public int DepthLimit;
    }
    public sealed class SnapshotComparison
    {
        public long AddedNodes, RemovedNodes, AddedEdges, RemovedEdges, UnchangedEdges;
        public List<GraphEdge> AddedSample = new List<GraphEdge>();
        public List<GraphEdge> RemovedSample = new List<GraphEdge>();
    }
    public sealed partial class GraphIndex
    {
        private static int CapabilityWeight(string type)
        {
            switch(type)
            {
                case "DCSync": case "GenericAll": case "WriteDacl": return 40;
                case "AddMember": case "AddSelf": case "WriteOwner": case "Owns":
                case "ForceChangePassword": case "AddKeyCredentialLink": return 35;
                case "MemberOf": return 0;
                case "HasSession": return 15;
                default: return 25;
            }
        }
        private static string FindingId(List<GraphEdge> steps)
        {
            // Length prefixes prevent ambiguous identifiers; normalize Windows identity casing.
            var text = new StringBuilder();
            foreach(var e in steps)
                foreach(string token in new[] { e.Source, e.Target, e.EdgeType })
                { string value=token.ToUpperInvariant(); text.Append(value.Length).Append(':').Append(value); }
            using(var hash=SHA256.Create())
                return BitConverter.ToString(hash.ComputeHash(Encoding.UTF8.GetBytes(text.ToString()))).Replace("-", "").ToLowerInvariant();
        }
        public long DirectMemberCount(string id)
        {
            using(var s=new Statement(this,"SELECT count(*) FROM edges WHERE target=?1 AND bucket='memberof' AND source<>target"))
            { s.Bind(1,id); s.Read(); return long.Parse(s.Text(0)); }
        }
        public List<string[]> DomainTargets() { return Query("SELECT id,name FROM nodes WHERE kind='domains'",2); }
        // One reverse BFS from all privileged targets. Each identity retains one shortest
        // recorded chain. The visit, depth and finding caps bound memory and report size.
        public ExposureAnalysis AnalyzeExposures(string[] targets, int maxVisited, int maxFindings, int maxDepth)
        {
            if(maxVisited<1 || maxFindings<1 || maxDepth<1) throw new ArgumentOutOfRangeException();
            var result=new ExposureAnalysis { DepthLimit=maxDepth };
            var next=new Dictionary<string,GraphEdge>(StringComparer.OrdinalIgnoreCase);
            var depths=new Dictionary<string,int>(StringComparer.OrdinalIgnoreCase);
            var queue=new Queue<string>();
            var allowed=new HashSet<string>(GraphRelationships.FilterTypes(),StringComparer.OrdinalIgnoreCase);
            foreach(string target in targets)
            {
                if(next.ContainsKey(target)) continue;
                if(next.Count>=maxVisited) { result.Truncated=true; break; }
                next.Add(target,new GraphEdge()); depths.Add(target,0); queue.Enqueue(target);
            }
            using(var incoming=Incoming())
            {
                while(queue.Count>0 && !result.Truncated)
                {
                    string current=queue.Dequeue();
                    incoming.Bind(1,current);
                    while(incoming.Read())
                    {
                        var e=ReadEdge(incoming,current);
                        if(!allowed.Contains(e.EdgeType) || next.ContainsKey(e.Source)) continue;
                        if(depths[current]>=maxDepth || next.Count>=maxVisited) { result.Truncated=true; break; }
                        next.Add(e.Source,e);depths.Add(e.Source,depths[current]+1);queue.Enqueue(e.Source);
                        var path=new List<GraphEdge>(); string id=e.Source; int weight=0; bool missing=false;
                        while(next[id].Source!=null) {var step=next[id];path.Add(step);weight=Math.Max(weight,CapabilityWeight(step.EdgeType));id=step.Target;}
                        // Pure memberships are expected context, not a security finding.
                        if(weight==0)continue;
                        foreach(var step in path)if(Node(step.Source)==null)missing=true;
                        var finding=new ExposureFinding {Source=e.Source,Target=id,Steps=path,MissingObjects=missing};
                        finding.Id=FindingId(path);finding.Score=30+weight;
                        finding.Reasons.Add("Recorded chain reaches a recognized privileged group or collected domain (+30).");
                        finding.Reasons.Add("Strongest permission or access capability on this chain (+"+weight+").");
                        var source=Node(e.Source);
                        if(source!=null && source[1]=="groups")
                        {
                            finding.DirectMembers=DirectMemberCount(e.Source);
                            int breadth=finding.DirectMembers>=100?15:finding.DirectMembers>0?5:0;
                            finding.Score+=breadth;
                            if(breadth>0)finding.Reasons.Add(finding.DirectMembers+" recorded direct group members (+"+breadth+").");
                        }
                        if(path.Count<=2){finding.Score+=5;finding.Reasons.Add("At most two recorded hops (+5).");}
                        if(missing){finding.Score-=10;finding.Reasons.Add("One or more source objects are outside the supplied object data (-10; validate identity).");}
                        finding.Priority=finding.Score>=65?"High review priority":"Medium review priority";
                        result.Findings.Add(finding);
                        if(result.Findings.Count>=maxFindings){result.Truncated=true;break;}
                    }
                    incoming.Reset();
                }
            }
            result.Visited=next.Count;
            result.Findings.Sort((a,b)=>{int order=b.Score.CompareTo(a.Score);return order!=0?order:StringComparer.Ordinal.Compare(a.Id,b.Id);});
            return result;
        }
        public bool ContainsPath(List<GraphEdge> steps)
        {
            using(var s=new Statement(this,@"SELECT 1 FROM edges WHERE target=?1 AND source=?2 AND type=?3
                AND bucket IN ('acl','access','memberof') AND source_dn=0 AND target_dn=0
                AND (bucket<>'memberof' OR NOT EXISTS(SELECT 1 FROM nodes WHERE id=?1 AND security_enabled='false')) LIMIT 1"))
                foreach(var e in steps){s.Bind(1,e.Target);s.Bind(2,e.Source);s.Bind(3,e.EdgeType);bool found=s.Read();s.Reset();if(!found)return false;}
            return steps.Count>0;
        }
        public List<string[]> ObjectRelationships(string id, int limit)
        {
            if(limit<1 || limit>1000)throw new ArgumentOutOfRangeException("limit");
            var rows=new List<string[]>();
            using(var s=new Statement(this,"SELECT source,target,type,bucket FROM edges WHERE source=?1 OR target=?1 LIMIT "+limit))
            {s.Bind(1,id);while(s.Read())rows.Add(new[]{s.Text(0),s.Text(1),s.Text(2),s.Text(3)});}
            return rows;
        }
        public SnapshotComparison CompareSnapshot(string baselinePath)
        {
            if(!File.Exists(baselinePath))throw new FileNotFoundException("Baseline graph index was not found.",baselinePath);
            using(var attach=new Statement(this,"ATTACH DATABASE ?1 AS baseline")){attach.Bind(1,Path.GetFullPath(baselinePath));attach.Read();}
            try
            {
                var r=new SnapshotComparison();
                r.AddedNodes=Scalar("SELECT count(*) FROM nodes n WHERE NOT EXISTS(SELECT 1 FROM baseline.nodes b WHERE b.id=n.id)");
                r.RemovedNodes=Scalar("SELECT count(*) FROM baseline.nodes n WHERE NOT EXISTS(SELECT 1 FROM main.nodes b WHERE b.id=n.id)");
                string added=@"FROM main.edges e WHERE NOT EXISTS(SELECT 1 FROM baseline.edges b WHERE
                    b.target=e.target AND b.bucket=e.bucket AND b.source=e.source AND b.type=e.type AND b.source_dn=e.source_dn AND b.target_dn=e.target_dn)";
                string removed=@"FROM baseline.edges e WHERE NOT EXISTS(SELECT 1 FROM main.edges b WHERE
                    b.target=e.target AND b.bucket=e.bucket AND b.source=e.source AND b.type=e.type AND b.source_dn=e.source_dn AND b.target_dn=e.target_dn)";
                r.AddedEdges=Scalar("SELECT count(*) "+added);r.RemovedEdges=Scalar("SELECT count(*) "+removed);
                r.UnchangedEdges=Scalar("SELECT count(*) FROM main.edges")-r.AddedEdges;
                foreach(var row in Query("SELECT source,target,type "+added+" LIMIT 50",3))r.AddedSample.Add(new GraphEdge{Source=row[0],Target=row[1],EdgeType=row[2]});
                foreach(var row in Query("SELECT source,target,type "+removed+" LIMIT 50",3))r.RemovedSample.Add(new GraphEdge{Source=row[0],Target=row[1],EdgeType=row[2]});
                return r;
            }
            finally{Execute("DETACH DATABASE baseline");}
        }
        private long Scalar(string sql){using(var s=new Statement(this,sql)){s.Read();return long.Parse(s.Text(0));}}
    }
}







namespace BH.Native
{
    public sealed class DiskAnalysisProgress
    {
        public long Visited, Processed, Findings, Pending;
        public string Status, StopReason;
        public double ElapsedSeconds;
        public int Depth;
    }
    public sealed partial class GraphIndex
    {
        private string DeepValue(string key)
        {
            using(var s=new Statement(this,"SELECT value FROM analysis_meta WHERE key=?1"))
            {s.Bind(1,key);return s.Read()?s.Text(0):null;}
        }
        private void SetDeepValue(string key,string value)
        {
            using(var s=new Statement(this,"INSERT OR REPLACE INTO analysis_meta VALUES(?1,?2)"))
            {s.Bind(1,key);s.Bind(2,value);s.Read();}
        }
        public bool HasDiskAnalysis()
        {
            return Scalar("SELECT count(*) FROM sqlite_master WHERE type='table' AND name='analysis_meta'")>0;
        }
        public string DiskSourceFingerprint(){return HasDiskAnalysis()?DeepValue("source"):null;}
        public void PrepareDiskAnalysis(string[] targets,string fingerprint)
        {if(!HasDiskAnalysis())InitializeDiskAnalysis(targets,fingerprint);}
        public DiskAnalysisProgress DiskAnalysisState()
        {
            if(!HasDiskAnalysis())return new DiskAnalysisProgress {Status="NotStarted",StopReason="No saved analysis"};
            return new DiskAnalysisProgress {
                Visited=long.Parse(DeepValue("visited")),Processed=long.Parse(DeepValue("processed")),
                Findings=long.Parse(DeepValue("findings")),Status=DeepValue("status"),StopReason=DeepValue("reason"),
                Pending=long.Parse(DeepValue("visited"))-long.Parse(DeepValue("processed")),Depth=int.Parse(DeepValue("depth"))
            };
        }
        private void InitializeDiskAnalysis(string[] targets,string fingerprint)
        {
            Execute("BEGIN IMMEDIATE");
            try {
            Execute(@"CREATE TABLE analysis_meta(key TEXT PRIMARY KEY,value TEXT) WITHOUT ROWID;
                CREATE TABLE analysis_nodes(seq INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT COLLATE NOCASE UNIQUE,
                next_id TEXT,edge_type TEXT,root TEXT,depth INTEGER,weight INTEGER,missing INTEGER,
                members INTEGER,score INTEGER,processed INTEGER DEFAULT 0,
                cursor_bucket TEXT DEFAULT '',cursor_source TEXT DEFAULT '',cursor_type TEXT DEFAULT '');
                CREATE INDEX analysis_queue ON analysis_nodes(seq) WHERE processed=0;
                CREATE INDEX analysis_rank ON analysis_nodes(score DESC,seq) WHERE weight>0;");
                using(var insert=new Statement(this,@"INSERT OR IGNORE INTO analysis_nodes
                    (id,root,depth,weight,missing,members,score) VALUES(?1,?1,0,0,0,0,0)"))
                    foreach(string id in targets){insert.Bind(1,id);insert.Read();insert.Reset();}
                SetDeepValue("version","1");SetDeepValue("source",fingerprint);
                SetDeepValue("queue_format","partial-v1");
                var canonical=(string[])targets.Clone();Array.Sort(canonical,StringComparer.OrdinalIgnoreCase);
                SetDeepValue("targets",string.Join("\n",canonical).ToUpperInvariant());
                SetDeepValue("visited",Scalar("SELECT count(*) FROM analysis_nodes").ToString(CultureInfo.InvariantCulture));
                SetDeepValue("processed","0");SetDeepValue("findings","0");SetDeepValue("depth","0");
                SetDeepValue("status","Ready");SetDeepValue("reason","Ready to analyze");Execute("COMMIT");
            }catch{Execute("ROLLBACK");throw;}
        }
        private void SaveDiskState(DiskAnalysisProgress p)
        {
            SetDeepValue("visited",p.Visited.ToString(CultureInfo.InvariantCulture));
            SetDeepValue("processed",p.Processed.ToString(CultureInfo.InvariantCulture));
            SetDeepValue("findings",p.Findings.ToString(CultureInfo.InvariantCulture));
            SetDeepValue("depth",p.Depth.ToString(CultureInfo.InvariantCulture));
            SetDeepValue("status",p.Status);SetDeepValue("reason",p.StopReason);
        }
        // A fixed-size batch is read before writes. Both the FIFO frontier and predecessor
        // links live in SQLite. Edge cursors are committed with discovered identities, so a
        // stopped or interrupted batch is replayed without skipping or duplicating work.
        public DiskAnalysisProgress AnalyzeDisk(string[] targets,string fingerprint,int depthLimit,long visitLimit,
            int secondsLimit,string cancelFile,Action<DiskAnalysisProgress> progress)
        {
            if(depthLimit<0 || visitLimit<0 || secondsLimit<0)throw new ArgumentOutOfRangeException();
            if(!HasDiskAnalysis())InitializeDiskAnalysis(targets,fingerprint);
            var canonical=(string[])targets.Clone();Array.Sort(canonical,StringComparer.OrdinalIgnoreCase);
            if(DeepValue("version")!="1" || DeepValue("source")!=fingerprint ||
                DeepValue("targets")!=string.Join("\n",canonical).ToUpperInvariant())
                throw new InvalidDataException("Saved analysis belongs to a different snapshot or target set. Use a new output folder.");
            if(DeepValue("queue_format")!="partial-v1")
            {
                Execute("BEGIN IMMEDIATE");
                try{Execute("DROP INDEX analysis_queue; CREATE INDEX analysis_queue ON analysis_nodes(seq) WHERE processed=0;");SetDeepValue("queue_format","partial-v1");Execute("COMMIT");}
                catch{Execute("ROLLBACK");throw;}
            }
            var state=DiskAnalysisState();var clock=Stopwatch.StartNew();double lastUpdate=-2;
            if(state.Status=="Completed")return state;
            state.Status="Running";state.StopReason="Search in progress";
            var allowed=new HashSet<string>(GraphRelationships.FilterTypes(),StringComparer.OrdinalIgnoreCase);
            bool transaction=false;int batches=0;double lastCheckpoint=0;
            using(var frontier=new Statement(this,@"SELECT seq,id,root,depth,weight,missing,cursor_bucket,cursor_source,cursor_type
                FROM analysis_nodes WHERE processed=0 ORDER BY seq LIMIT 1"))
            using(var incoming=new Statement(this,@"SELECT source,type,bucket FROM edges WHERE target=?1
                AND bucket IN ('acl','memberof','access') AND source<>target AND source_dn=0 AND target_dn=0
                AND (bucket<>'memberof' OR NOT EXISTS(SELECT 1 FROM nodes WHERE id=?1 AND security_enabled='false'))
                AND (bucket,source,type)>(?2,?3,?4)
                ORDER BY bucket,source,type LIMIT 256"))
            using(var exists=new Statement(this,"SELECT 1 FROM analysis_nodes WHERE id=?1"))
            using(var insert=new Statement(this,@"INSERT INTO analysis_nodes
                (id,next_id,edge_type,root,depth,weight,missing,members,score) VALUES(?1,?2,?3,?4,?5,?6,?7,?8,?9)"))
            using(var cursor=new Statement(this,@"UPDATE analysis_nodes SET cursor_bucket=?2,cursor_source=?3,cursor_type=?4,
                processed=?5 WHERE seq=?1"))
            {
                while(true)
                {
                    state.ElapsedSeconds=clock.Elapsed.TotalSeconds;state.Pending=state.Visited-state.Processed;
                    if(cancelFile!=null && File.Exists(cancelFile)){state.Status="Cancelled";state.StopReason="Cancellation requested; resume is available";break;}
                    if(secondsLimit>0 && clock.Elapsed.TotalSeconds>=secondsLimit){state.Status="TimeLimit";state.StopReason="Time budget reached; resume is available";break;}
                    if(!frontier.Read()){frontier.Reset();state.Status="Completed";state.StopReason="Frontier exhausted for supported relationships and the selected targets";break;}
                    string sequence=frontier.Text(0),id=frontier.Text(1),root=frontier.Text(2);
                    int depth=int.Parse(frontier.Text(3)),weight=int.Parse(frontier.Text(4)),missing=int.Parse(frontier.Text(5));
                    string lastBucket=frontier.Text(6),lastSource=frontier.Text(7),lastType=frontier.Text(8);frontier.Reset();
                    state.Depth=depth;
                    incoming.Bind(1,id);incoming.Bind(2,lastBucket);incoming.Bind(3,lastSource);incoming.Bind(4,lastType);
                    var batch=new List<string[]>();while(incoming.Read())batch.Add(new[]{incoming.Text(0),incoming.Text(1),incoming.Text(2)});incoming.Reset();
                    if(!transaction){Execute("BEGIN IMMEDIATE");transaction=true;}
                    try {
                        bool blocked=false;
                        foreach(var edge in batch)
                        {
                            bool found;
                            exists.Bind(1,edge[0]);found=exists.Read();exists.Reset();
                            if(allowed.Contains(edge[1]) && !found)
                            {
                                if(depthLimit>0 && depth>=depthLimit){state.Status="DepthLimit";state.StopReason="Depth budget reached; raise it or select Deep analysis to resume";blocked=true;break;}
                                if(visitLimit>0 && state.Visited>=visitLimit){state.Status="VisitLimit";state.StopReason="Identity budget reached; raise it to resume";blocked=true;break;}
                                int childWeight=Math.Max(weight,CapabilityWeight(edge[1]));
                                var node=Node(edge[0]);int childMissing=missing!=0 || node==null?1:0;
                                long members=node!=null && node[1]=="groups" && childWeight>0?DirectMemberCount(edge[0]):0;
                                int score=childWeight==0?0:30+childWeight+(depth+1<=2?5:0)+(members>=100?15:members>0?5:0)-(childMissing!=0?10:0);
                                insert.Bind(1,edge[0]);insert.Bind(2,id);insert.Bind(3,edge[1]);insert.Bind(4,root);
                                insert.Bind(5,(depth+1).ToString(CultureInfo.InvariantCulture));insert.Bind(6,childWeight.ToString(CultureInfo.InvariantCulture));
                                insert.Bind(7,childMissing.ToString());insert.Bind(8,members.ToString(CultureInfo.InvariantCulture));insert.Bind(9,score.ToString());
                                insert.Read();insert.Reset();state.Visited++;if(childWeight>0)state.Findings++;
                            }
                            lastBucket=edge[2];lastSource=edge[0];lastType=edge[1];
                        }
                        bool done=!blocked && batch.Count<256;
                        cursor.Bind(1,sequence);cursor.Bind(2,lastBucket);cursor.Bind(3,lastSource);cursor.Bind(4,lastType);cursor.Bind(5,done?"1":"0");cursor.Read();cursor.Reset();
                        if(done)state.Processed++;batches++;
                        if(blocked || batches>=128 || clock.Elapsed.TotalSeconds-lastCheckpoint>=1)
                        {SaveDiskState(state);Execute("COMMIT");transaction=false;batches=0;lastCheckpoint=clock.Elapsed.TotalSeconds;}
                        if(blocked)break;
                    }catch{if(transaction){Execute("ROLLBACK");transaction=false;}throw;}
                    if(progress!=null && clock.Elapsed.TotalSeconds-lastUpdate>=1){lastUpdate=clock.Elapsed.TotalSeconds;state.ElapsedSeconds=clock.Elapsed.TotalSeconds;state.Pending=state.Visited-state.Processed;progress(state);}
                }
            }
            state.Pending=state.Visited-state.Processed;state.ElapsedSeconds=clock.Elapsed.TotalSeconds;
            if(!transaction)Execute("BEGIN IMMEDIATE");try{SaveDiskState(state);Execute("COMMIT");}catch{Execute("ROLLBACK");throw;}
            if(progress!=null)progress(state);return state;
        }
        public List<ExposureFinding> DiskFindingPage(int afterScore,long afterSequence,int limit)
        {
            if(limit<1 || limit>200)throw new ArgumentOutOfRangeException("limit");
            var result=new List<ExposureFinding>();if(!HasDiskAnalysis())return result;
            var entries=new List<string[]>();
            // Two range seeks handle mixed score-descending/sequence-ascending order
            // without rescanning previously viewed candidates through a large OR filter.
            ReadDiskPage(entries,"score=?1 AND seq>?2",afterScore,afterSequence,limit);
            if(entries.Count<limit)ReadDiskPage(entries,"score<?1",afterScore,afterSequence,limit-entries.Count);
            foreach(var row in entries)
            {
                var f=new ExposureFinding {Source=row[0],Target=row[1],HopCount=int.Parse(row[2]),MissingObjects=row[4]=="1",
                    DirectMembers=long.Parse(row[5]),Score=int.Parse(row[6]),Sequence=long.Parse(row[7])};
                f.Priority=f.Score>=65?"High review priority":"Medium review priority";
                f.Reasons.Add("Recorded chain reaches a recognized privileged group or collected domain (+30).");
                f.Reasons.Add("Strongest permission or access capability on this chain (+"+row[3]+").");
                if(f.DirectMembers>0)f.Reasons.Add(f.DirectMembers+" recorded direct group members (+"+(f.DirectMembers>=100?15:5)+").");
                if(f.HopCount<=2)f.Reasons.Add("At most two recorded hops (+5).");
                if(f.MissingObjects)f.Reasons.Add("One or more source objects are outside the supplied object data (-10; validate identity).");
                string current=f.Source;
                using(var next=new Statement(this,"SELECT next_id,edge_type FROM analysis_nodes WHERE id=?1"))
                    while(f.Steps.Count<256)
                    {next.Bind(1,current);bool found=next.Read();string target=found?next.Text(0):null,type=found?next.Text(1):null;next.Reset();if(target==null)break;f.Steps.Add(new GraphEdge{Source=current,Target=target,EdgeType=type});current=target;}
                f.PathLimited=f.Steps.Count<f.HopCount;f.NextPathId=f.PathLimited?current:null;
                // Stable path IDs are retained for fully embedded chains; long chains use identity+target.
                f.Id=f.PathLimited?FindingId(new List<GraphEdge>{new GraphEdge{Source=f.Source,Target=f.Target,EdgeType="LongRecordedChain"}}):FindingId(f.Steps);
                result.Add(f);
            }
            return result;
        }
        private void ReadDiskPage(List<string[]> rows,string predicate,int score,long sequence,int limit)
        {
            using(var page=new Statement(this,@"SELECT id,root,depth,weight,missing,members,score,seq FROM analysis_nodes
                WHERE weight>0 AND "+predicate+" ORDER BY score DESC,seq LIMIT "+limit))
            {
                page.Bind(1,score.ToString());if(predicate.IndexOf("?2",StringComparison.Ordinal)>=0)page.Bind(2,sequence.ToString());
                while(page.Read()){var row=new string[8];for(int i=0;i<8;i++)row[i]=page.Text(i);rows.Add(row);}
            }
        }
        public List<GraphEdge> DiskPathPage(string start,int limit)
        {
            if(limit<1 || limit>1000)throw new ArgumentOutOfRangeException("limit");
            var rows=new List<GraphEdge>();
            using(var next=new Statement(this,"SELECT next_id,edge_type FROM analysis_nodes WHERE id=?1"))
                while(rows.Count<limit){next.Bind(1,start);bool found=next.Read();string target=found?next.Text(0):null,type=found?next.Text(1):null;next.Reset();if(target==null)break;rows.Add(new GraphEdge{Source=start,Target=target,EdgeType=type});start=target;}
            return rows;
        }
    }
}
















