            return ViewerJson.Map("Source",VNode(start),"Target",VNode(root),"HopCount",depth,"Score",score,
                "Priority",score>=65?"High review priority":"Medium review priority","Observation","Recorded path",
                "Reasons",reasons,
                "Evidence","Recorded relationships from the selected index; effective access requires validation.","MissingObjects",missing,
                "Steps",VEdges(edges),"PathLimited",edges.Count<depth,"NextPathId",edges.Count<depth?next:null);
        }
        public object ViewerObject(string id)
        {
            var node=VNode(id);string record=null;bool limited=false;
            using(var s=new Statement(this,"SELECT record FROM nodes WHERE id=?1"))
            {
                s.Bind(1,id);
                if(s.Read())
                {
                    // Cap compressed input and decompressed output independently.
                    int bytes=sqlite3_column_bytes(s.handle,0);
                    if(bytes>2097152)limited=true;
                    else if(sqlite3_column_type(s.handle,0)!=4){record=s.Text(0);if(record!=null&&record.Length>1048576){record=null;limited=true;}}
                    else
                    {
                        var data=new byte[bytes];Marshal.Copy(sqlite3_column_blob(s.handle,0),data,0,bytes);
                        using(var input=new MemoryStream(data))using(var gzip=new GZipStream(input,CompressionMode.Decompress))using(var reader=new StreamReader(gzip,Encoding.UTF8))
                        {var buffer=new char[4096];var b=new StringBuilder();int count;while((count=reader.Read(buffer,0,buffer.Length))>0){if(b.Length+count>1048576){limited=true;break;}b.Append(buffer,0,count);}if(!limited)record=b.ToString();}
                    }
                }
            }
            node["Record"]=record;node["Limited"]=limited;return node;
        }
        // Incoming relationships use the index's target key. Outgoing browsing uses bounded
        // primary-key windows; the scanner does not yet create a source-side index.
        public object ViewerRelationships(string id,string direction,string target,string bucket,string source,string type)
        {
            var rows=new List<object>();int scanned=0;bool more=false;
            string sql=direction=="in"?"SELECT target,bucket,source,type FROM edges WHERE target=?1 AND (bucket,source,type)>(?2,?3,?4) ORDER BY bucket,source,type LIMIT 51":
                "SELECT target,bucket,source,type FROM edges WHERE (target,bucket,source,type)>(?1,?2,?3,?4) ORDER BY target,bucket,source,type LIMIT 50001";
            using(var s=new Statement(this,sql))
            {
                s.Bind(1,direction=="in"?id:target);s.Bind(2,bucket);s.Bind(3,source);s.Bind(4,type);
                while(s.Read())
                {
                    if(scanned==50000||rows.Count==50){more=true;break;}ViewerCheck();scanned++;
                    target=s.Text(0);bucket=s.Text(1);source=s.Text(2);type=s.Text(3);
                    if(direction=="in"||string.Equals(source,id,StringComparison.OrdinalIgnoreCase))rows.Add(VEdge(new GraphEdge{Source=source,Target=target,EdgeType=type}));
                }
            }
            return ViewerJson.Map("Rows",rows,"More",more,"Scanned",scanned,"Target",target,"Bucket",bucket,"Source",source,"Type",type);
        }
        public object ViewerShortestPath(string source,string target,int maxVisited)
        {
            var visited=new Dictionary<string,GraphEdge>(StringComparer.OrdinalIgnoreCase);var queue=new Queue<string>();
            visited.Add(target,new GraphEdge());queue.Enqueue(target);string status="NoPath";bool found=string.Equals(source,target,StringComparison.OrdinalIgnoreCase);
            while(queue.Count>0&&!found)
            {
                ViewerCheck();string current=queue.Dequeue();
                using(var s=Incoming())
                {
                    s.Bind(1,current);
                    while(s.Read())
                    {
                        ViewerCheck();string from=s.Text(0);if(visited.ContainsKey(from))continue;
                        if(visited.Count>=maxVisited){status="VisitLimit";queue.Clear();break;}
                        visited.Add(from,new GraphEdge{Source=from,Target=current,EdgeType=s.Text(1)});
                        if(string.Equals(from,source,StringComparison.OrdinalIgnoreCase)){found=true;break;}queue.Enqueue(from);
                    }
                }
            }
            var edges=new List<GraphEdge>();int hops=0;string next=source;
            if(found){status="Found";while(!string.Equals(next,target,StringComparison.OrdinalIgnoreCase)){var e=visited[next];hops++;if(edges.Count<128)edges.Add(e);next=e.Target;}}
            return ViewerJson.Map("Status",status,"Visited",visited.Count,"Steps",VEdges(edges),"HopCount",hops,"PathLimited",hops>edges.Count,
                "NextPathId",hops>edges.Count?edges[edges.Count-1].Target:null,"Source",VNode(source),"Target",VNode(target));
        }
    }

    public static class ViewerJson
    {
        public static Dictionary<string,object> Map(params object[] pairs)
        {var result=new Dictionary<string,object>();for(int i=0;i<pairs.Length;i+=2)result.Add((string)pairs[i],pairs[i+1]);return result;}
        public static string Encode(object value){var b=new StringBuilder();Write(b,value,0);return b.ToString();}
        private static void Write(StringBuilder b,object value,int depth)
        {
            if(depth>24)throw new IOException("Response nesting limit");
            if(value==null){b.Append("null");return;}
            var text=value as string;if(text!=null)
            {b.Append('"');foreach(char c in text){if(c=='"'||c=='\\')b.Append('\\').Append(c);else if(c<32||c=='<'||c=='>'||c=='&'||c=='\u2028'||c=='\u2029')b.Append("\\u").Append(((int)c).ToString("x4"));else b.Append(c);}b.Append('"');return;}
            if(value is bool){b.Append((bool)value?"true":"false");return;}
            var map=value as IDictionary;if(map!=null){b.Append('{');bool first=true;foreach(DictionaryEntry e in map){if(!first)b.Append(',');first=false;Write(b,Convert.ToString(e.Key,CultureInfo.InvariantCulture),depth+1);b.Append(':');Write(b,e.Value,depth+1);}b.Append('}');return;}
            var list=value as IEnumerable;if(list!=null){b.Append('[');bool first=true;foreach(object item in list){if(!first)b.Append(',');first=false;Write(b,item,depth+1);}b.Append(']');return;}
            if(value is IFormattable){b.Append(((IFormattable)value).ToString(null,CultureInfo.InvariantCulture));return;}
            var fields=new Dictionary<string,object>();foreach(var field in value.GetType().GetFields(BindingFlags.Instance|BindingFlags.Public))fields[field.Name]=field.GetValue(value);Write(b,fields,depth+1);
        }
    }

    public sealed class ViewerServer : IDisposable
    {
        private readonly string path,html,token;
        private readonly TcpListener listener;
        private readonly FileStream fileLock;
        private readonly Semaphore slots=new Semaphore(4,4);
        private Thread acceptThread;
        private volatile bool running;
        public string Url { get; private set; }
        public bool IsRunning { get { return running; } }
        public ViewerServer(string indexPath,string page)
        {
            path=Path.GetFullPath(indexPath);html=page;
            fileLock=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.Read);
            try
            {
                var header=new byte[20];if(fileLock.Read(header,0,header.Length)!=20||Encoding.ASCII.GetString(header,0,16)!="SQLite format 3\0")throw new IOException("Select a BHTest SQLite graph index.");
                if(header[18]!=1||header[19]!=1||File.Exists(path+"-wal")||File.Exists(path+"-journal"))throw new IOException("Select a completed, standalone graph.sqlite snapshot, without a WAL or recovery journal.");
                using(var db=new GraphIndex(path,false)){db.ViewerBudget();db.Node("__viewer_schema_check__");}
                var secret=new byte[32];using(var rng=RandomNumberGenerator.Create())rng.GetBytes(secret);token=Convert.ToBase64String(secret);
                listener=new TcpListener(IPAddress.Loopback,0);listener.Start(16);int port=((IPEndPoint)listener.LocalEndpoint).Port;
                Url="http://127.0.0.1:"+port+"/#"+token;running=true;acceptThread=new Thread(Accept);acceptThread.IsBackground=true;acceptThread.Start();
            }
            catch{fileLock.Dispose();throw;}
        }
        private void Accept()
        {
            while(running)
            {
                TcpClient client=null;
                try
                {
                    client=listener.AcceptTcpClient();
                    if(!slots.WaitOne(0)){client.Close();continue;}
                    var owned=client;ThreadPool.QueueUserWorkItem(delegate(object unused){try{Handle(owned);}catch{}finally{owned.Close();slots.Release();}});
                }
                catch{if(client!=null)client.Close();if(!running)break;}
            }
        }
        private void Respond(NetworkStream stream,int status,string type,string body)
        {
            byte[] payload=Encoding.UTF8.GetBytes(body);string reason=status==200?"OK":status==403?"Forbidden":status==404?"Not Found":status==400?"Bad Request":"Query Error";
            byte[] header=Encoding.ASCII.GetBytes("HTTP/1.1 "+status+" "+reason+"\r\nContent-Type: "+type+"; charset=utf-8\r\nContent-Length: "+payload.Length+"\r\nConnection: close\r\nCache-Control: no-store\r\nX-Content-Type-Options: nosniff\r\nReferrer-Policy: no-referrer\r\nContent-Security-Policy: default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; connect-src 'self'; img-src 'self' data:; frame-ancestors 'none'; base-uri 'none'; form-action 'none'\r\n\r\n");
            stream.Write(header,0,header.Length);stream.Write(payload,0,payload.Length);stream.Flush();
        }
        private bool Authorized(string supplied)
        {string expected="Bearer "+token;int difference=(supplied??"").Length^expected.Length;for(int i=0;i<expected.Length;i++)difference|=expected[i]^(supplied!=null&&i<supplied.Length?supplied[i]:0);return difference==0;}
        private static string Arg(Dictionary<string,string> args,string key)
        {string value;return args.TryGetValue(key,out value)?value:"";}
        private static long Number(Dictionary<string,string> args,string key,long fallback,long min,long max)
        {string value=Arg(args,key);long number;if(value.Length==0)return fallback;if(!long.TryParse(value,NumberStyles.Integer,CultureInfo.InvariantCulture,out number)||number<min||number>max)throw new ArgumentException("Invalid "+key);return number;}
        private void Handle(TcpClient client)
        {
            client.ReceiveTimeout=3000;client.SendTimeout=10000;using(var stream=client.GetStream())
            {
                var clock=Stopwatch.StartNew();var b=new StringBuilder();int c;
                while(b.Length<16384&&clock.ElapsedMilliseconds<3000&&(c=stream.ReadByte())>=0){if(c>127||c==0)return;b.Append((char)c);if(b.Length>=4&&b.ToString(b.Length-4,4)=="\r\n\r\n")break;}
                if(!b.ToString().EndsWith("\r\n\r\n",StringComparison.Ordinal)){Respond(stream,400,"text/plain","Invalid request headers");return;}
                var lines=b.ToString().Split(new string[]{"\r\n"},StringSplitOptions.None);var request=lines[0].Split(' ');var headers=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);
                if(request.Length!=3||request[2]!="HTTP/1.1"||!request[1].StartsWith("/",StringComparison.Ordinal)){Respond(stream,400,"text/plain","Invalid request");return;}
                foreach(string line in lines){if(line==lines[0]||line.Length==0)continue;int colon=line.IndexOf(':');if(colon<1||headers.ContainsKey(line.Substring(0,colon))){Respond(stream,400,"text/plain","Invalid headers");return;}headers.Add(line.Substring(0,colon),line.Substring(colon+1).Trim());}
                string origin="http://127.0.0.1:"+((IPEndPoint)listener.LocalEndpoint).Port;
                if(Arg(headers,"Host")!=origin.Substring(7)||(Arg(headers,"Origin").Length>0&&Arg(headers,"Origin")!=origin)||Arg(headers,"Sec-Fetch-Site")=="cross-site")
                {Respond(stream,403,"text/plain","Local origin required");return;}
                if(headers.ContainsKey("Transfer-Encoding")||(headers.ContainsKey("Content-Length")&&Arg(headers,"Content-Length")!="0"))
                {Respond(stream,400,"text/plain","Request bodies are not accepted");return;}
                if(request[0]=="GET"&&request[1]=="/"){Respond(stream,200,"text/html",html);return;}
                if(!Authorized(Arg(headers,"Authorization"))){Respond(stream,403,"text/plain","Viewer session required");return;}
                if(request[0]=="POST"&&request[1]=="/api/stop"){Respond(stream,200,"application/json","{\"Stopped\":true}");Stop();return;}
                if(request[0]!="GET"){Respond(stream,400,"text/plain","Unsupported method");return;}
                try
                {
                    int question=request[1].IndexOf('?');string route=question<0?request[1]:request[1].Substring(0,question);var args=new Dictionary<string,string>();
                    if(question>=0)foreach(string pair in request[1].Substring(question+1).Split('&')){int equals=pair.IndexOf('=');if(equals<0)throw new ArgumentException("Invalid query");string key=Uri.UnescapeDataString(pair.Substring(0,equals).Replace('+',' ')),value=Uri.UnescapeDataString(pair.Substring(equals+1).Replace('+',' '));if(value.Length>2048||args.ContainsKey(key))throw new ArgumentException("Invalid query");args.Add(key,value);}
                    object result;
                    using(var db=new GraphIndex(path,false))
                    {
                        db.ViewerBudget();
                        switch(route)
                        {
                            case "/api/summary":result=db.ViewerSummary();break;
                            case "/api/search":result=db.ViewerSearch(Arg(args,"q"),Arg(args,"after"));break;
                            case "/api/findings":result=db.ViewerFindings((int)Number(args,"score",int.MaxValue,0,int.MaxValue),Number(args,"sequence",0,0,long.MaxValue),Arg(args,"q"));break;
                            case "/api/recorded":result=db.ViewerRecordedPath(Arg(args,"id"));break;
                            case "/api/object":result=db.ViewerObject(Arg(args,"id"));break;
                            case "/api/relationships":if(Arg(args,"direction")!="in"&&Arg(args,"direction")!="out")throw new ArgumentException("Select incoming or outgoing");result=db.ViewerRelationships(Arg(args,"id"),Arg(args,"direction"),Arg(args,"target"),Arg(args,"bucket"),Arg(args,"source"),Arg(args,"type"));break;
                            case "/api/path":if(Arg(args,"source").Length==0||Arg(args,"target").Length==0)throw new ArgumentException("Source and target IDs required");result=db.ViewerShortestPath(Arg(args,"source"),Arg(args,"target"),(int)Number(args,"limit",50000,1,250000));break;
                            default:Respond(stream,404,"text/plain","Unknown route");return;
                        }
                    }
                    Respond(stream,200,"application/json",ViewerJson.Encode(result));
                }
                catch(ArgumentException e){Respond(stream,400,"application/json",ViewerJson.Encode(ViewerJson.Map("Error",e.Message)));}
                catch(Exception e){Respond(stream,422,"application/json",ViewerJson.Encode(ViewerJson.Map("Error",e.Message.IndexOf("SQLite error 9",StringComparison.Ordinal)>=0?"Query time limit reached. Narrow the query and retry.":e.Message)));}
            }
        }
        public void Stop(){running=false;listener.Stop();}
        public void Dispose(){Stop();if(acceptThread!=null)acceptThread.Join(4000);for(int i=0;i<4;i++)slots.WaitOne();fileLock.Dispose();slots.Release(4);}
    }
}












namespace BH.Native
{
    // A native Windows interface: no browser, WebView runtime, HTTP bridge, or sockets.
    public static class DesktopViewer
    {
        internal static readonly Dictionary<string,string[]> Guide=CreateGuide();
        private static Dictionary<string,string[]> CreateGuide()
        {
            var guide=new Dictionary<string,string[]>(StringComparer.OrdinalIgnoreCase);
            guide.Add("GenericAll",new string[]{"Full control","The source has broad control over the target directory object.","The dataset contains a GenericAll permission from the source to this target.","Control of an account, group, computer or policy can extend access to other resources. The effect depends on the target type.","Confirm the business owner and intended delegation. Review the target ACL, including inheritance, and remove unnecessary full-control grants.","A collected allow right approximates effective access; group tokens, deny entries and object protections still need checking.","Replace unnecessary full-control delegation with the specific permissions the role requires."});
guide.Add("GenericWrite",new string[]{"Write object properties","The source can change a broad set of properties on the target object.","A GenericWrite grant was recorded on the target.","Changing security-sensitive properties may create additional access, depending on the target.","Inspect the target type and delegated attributes. Replace broad write access with the specific permissions the role needs.","This does not mean the source can change every protected attribute or immediately take over the target.","Remove unnecessary broad property-write rights and delegate only the required attributes."});
guide.Add("WriteDacl",new string[]{"Change permissions","The source can change the permission list on the target.","A WriteDacl grant was recorded.","Someone controlling the source could grant additional access to the target.","Inspect who can edit this ACL and why. Remove unnecessary permission-management rights and check inheritance.","Confirm effective rights and protected-object behavior before deciding the grant is exploitable.","Remove unnecessary ACL-edit rights. If the grant is inherited, review its originating container."});
guide.Add("WriteOwner",new string[]{"Ownership control","The source owns the object or can change its owner.","Ownership or a WriteOwner permission appears in the collected data.","Ownership can enable changes to permissions, subject to owner-rights restrictions.","Confirm the intended owner. Review owner-rights entries and who can change ownership.","Ownership is a review signal; special owner-rights rules can restrict the resulting access.","Restrict who can change the owner and restore the intended ownership through an approved change."});
guide.Add("Owns",new string[]{"Ownership control","The source owns the object or can change its owner.","Ownership or a WriteOwner permission appears in the collected data.","Ownership can enable changes to permissions, subject to owner-rights restrictions.","Confirm the intended owner. Review owner-rights entries and who can change ownership.","Ownership is a review signal; special owner-rights rules can restrict the resulting access.","Confirm the intended owner, review owner-rights entries, and correct unauthorized ownership."});
guide.Add("ForceChangePassword",new string[]{"Reset another account’s password","The source has a password-reset right over the target account.","A ForceChangePassword grant was recorded.","An unnecessary reset delegation can allow someone to take control of another account.","Confirm the helpdesk or service delegation and its scope. Limit reset rights to the required accounts.","This is a permission observation, not evidence that any password was changed.","Limit password-reset delegation to the intended support role and account scope."});
guide.Add("AddMember",new string[]{"Change group membership","The source can add members, or add itself, to the target group.","The dataset records an AddMember or AddSelf relationship.","Joining a privileged group may grant that group’s access.","Check the group’s purpose, downstream access, and membership-management ACL. Restrict who can add members.","Membership management can be legitimate. Impact depends on the privileges of the target group.","Limit group-membership management to approved administrators or a narrowly scoped provisioning role."});
guide.Add("AddSelf",new string[]{"Change group membership","The source can add members, or add itself, to the target group.","The dataset records an AddMember or AddSelf relationship.","Joining a privileged group may grant that group’s access.","Check the group’s purpose, downstream access, and membership-management ACL. Restrict who can add members.","Membership management can be legitimate. Impact depends on the privileges of the target group.","Remove unnecessary self-membership rights from this group."});
guide.Add("DCSync",new string[]{"Directory replication rights","The source has the replication rights represented by this DCSync relationship on the domain.","The collector or imported dataset reports the required replication capability.","Unnecessary replication permissions can expose domain credential material.","Confirm this is a domain controller or an approved replication service. Review the domain-root replication ACL and remove unauthorized grants.","This records a capability, not a completed credential theft. Validate effective rights and the source data.","Retain replication permissions only for domain controllers and explicitly approved replication services."});
guide.Add("AllExtendedRights",new string[]{"Broad extended rights","The source has broad extended rights on the target.","An AllExtendedRights grant was recorded.","The available actions depend on the target, and can include sensitive account or domain operations.","Inspect the target’s extended rights and the business reason for the delegation. Prefer narrowly scoped rights.","Do not infer a particular attack from this label without checking the target and prerequisites.","Replace broad extended-right grants with only the approved individual rights."});
guide.Add("AdminTo",new string[]{"Local administrator access","The source is represented as an administrator of the target computer.","Native local-group collection or an imported dataset recorded an administrator relationship.","Control of the source may give administrative control of that computer and access to sensitive data.","Check the computer’s local Administrators group, nested memberships, device tier and intended support role.","Actual remote access also depends on policies, token filtering, credentials and network reachability.","Remove unnecessary local-administrator membership, including nested assignments through policy."});
guide.Add("CanRDP",new string[]{"Remote desktop membership","The source has a recorded relationship associated with Remote Desktop access to the target.","Endpoint group enumeration or an imported dataset recorded CanRDP.","Remote interactive access may expose applications and data on the computer.","Review Remote Desktop Users, logon allow/deny policies, MFA and network restrictions.","Group membership alone does not prove that a remote desktop logon will succeed.","Remove unnecessary Remote Desktop membership and review logon allow/deny policy."});
guide.Add("CanPSRemote",new string[]{"Remote management membership","The source has a recorded remote-management or DCOM relationship to the computer.","The relevant local group or an imported access relationship was collected.","An unnecessary management delegation may allow remote operations under suitable conditions.","Review the local group, endpoint configuration, authorization policy and network restrictions.","BHTest native collection observes group membership; it does not test whether remote execution succeeds.","Remove unnecessary remote-management membership and review endpoint authorization."});
guide.Add("ExecuteDCOM",new string[]{"Remote management membership","The source has a recorded remote-management or DCOM relationship to the computer.","The relevant local group or an imported access relationship was collected.","An unnecessary management delegation may allow remote operations under suitable conditions.","Review the local group, endpoint configuration, authorization policy and network restrictions.","BHTest native collection observes group membership; it does not test whether remote execution succeeds.","Remove unnecessary DCOM group membership and review application-specific launch permissions."});
guide.Add("HasSession",new string[]{"A user was observed logged on","The target user was reported as logged on to the source computer at collection time.","Endpoint enumeration or the imported data contained a session observation.","A privileged user on a lower-trust computer may increase exposure if that computer is compromised.","Confirm the session is current, check administrative logon practices, and separate privileged accounts from routine workstation use.","This can become stale quickly. It does not prove credentials are recoverable or that the user is still connected.","Move privileged administration to trusted administration hosts and end unneeded privileged sessions after coordinating with their owner."});
guide.Add("AllowedToAct",new string[]{"Resource-based delegation","The target computer’s delegation descriptor names the source as allowed to act on behalf of users.","The collector read the target’s resource-based delegation security descriptor.","Control of an allowed source account can permit impersonation to the target under suitable conditions.","Confirm the service dependency and approved delegating accounts. Review the target’s delegation descriptor.","User protections, protocol behavior and credentials affect the result; the relationship alone is not a successful impersonation.","Remove unauthorized principals from the target’s resource-based delegation descriptor."});
guide.Add("AllowedToDelegate",new string[]{"Constrained delegation","The source account has an allowed service target that resolves to this collected object.","An allowed-to-delegate SPN was resolved against the dataset’s service names.","Control of a delegation account may allow impersonation to the named service under suitable conditions.","Review the exact allowed services, protocol-transition setting, account ownership and protected-user policy.","An SPN-to-object link identifies a potential target. It does not prove every service on the computer is reachable or delegation will succeed.","Remove obsolete allowed-service targets and restrict delegation to approved service accounts and services."});
guide.Add("HasSIDHistory",new string[]{"Historical identity on an account","The source account contains the target SID in its SID history.","The collector read the account’s sIDHistory attribute.","Historical SIDs can retain access from an older identity or migration.","Confirm the migration purpose, expected history and remaining permissions. Remove obsolete history through an approved change.","Trust filtering and token behavior affect whether a historical SID grants access.","Remove obsolete SID history through the approved migration cleanup process after checking dependent access."});
guide.Add("ReadLAPSPassword",new string[]{"Read a managed account secret","The dataset represents access to a managed local or service account secret.","A supported secret-read relationship was present in the collected or imported dataset.","Reading a privileged managed password can extend control to its dependent systems.","Review the secret-read ACL, intended consumers and rotation controls. Limit readers to approved principals.","A relationship does not mean a password was read. Additional protection or decryption prerequisites may apply.","Restrict local administrator password readers and review the managed account’s scope and rotation."});
guide.Add("ReadGMSAPassword",new string[]{"Read a managed account secret","The dataset represents access to a managed local or service account secret.","A supported secret-read relationship was present in the collected or imported dataset.","Reading a privileged managed password can extend control to its dependent systems.","Review the secret-read ACL, intended consumers and rotation controls. Limit readers to approved principals.","A relationship does not mean a password was read. Additional protection or decryption prerequisites may apply.","Restrict managed-service password readers to approved service hosts and administrators."});
guide.Add("DumpSMSAPassword",new string[]{"Read a managed account secret","The dataset represents access to a managed local or service account secret.","A supported secret-read relationship was present in the collected or imported dataset.","Reading a privileged managed password can extend control to its dependent systems.","Review the secret-read ACL, intended consumers and rotation controls. Limit readers to approved principals.","A relationship does not mean a password was read. Additional protection or decryption prerequisites may apply.","Review access to this managed service account and restrict the hosts and principals that can obtain its secret."});
guide.Add("AddAllowedToAct",new string[]{"Change computer security settings","The source has a recorded right that may affect account restrictions or delegation-related settings.","A corresponding write permission was present in the dataset.","Changing these properties can create a new route to computer access under the relevant prerequisites.","Review the exact writable properties, object type and intended provisioning role. Remove excess delegation.","The right’s scope and the target’s protections must be verified; this is not proof of a complete attack chain.","Restrict writes that can change resource-based delegation on this computer."});
guide.Add("WriteAccountRestrictions",new string[]{"Change computer security settings","The source has a recorded right that may affect account restrictions or delegation-related settings.","A corresponding write permission was present in the dataset.","Changing these properties can create a new route to computer access under the relevant prerequisites.","Review the exact writable properties, object type and intended provisioning role. Remove excess delegation.","The right’s scope and the target’s protections must be verified; this is not proof of a complete attack chain.","Delegate only the account-restriction properties required by the provisioning role."});
guide.Add("AddKeyCredentialLink",new string[]{"Change key credentials","The source can change key-credential data associated with the target.","The dataset includes an AddKeyCredentialLink relationship.","An unauthorized credential change could create another way to authenticate as the target.","Review who can write key credentials, legitimate enrollment requirements, and recent credential changes.","Authentication infrastructure and target-specific prerequisites still apply.","Restrict writes to key-credential data and review existing credentials against approved enrollment."});
guide.Add("WriteSPN",new string[]{"Change service names","The source can change service principal names on the target account.","A WriteSPN relationship was recorded.","Service-name changes can affect authentication and create credential-exposure opportunities.","Confirm who manages this service account and which SPNs it requires. Restrict unauthorized SPN changes.","Target properties and authentication prerequisites determine the practical risk.","Restrict service-name changes to the approved service-account management role."});
guide.Add("WriteGPLink",new string[]{"Change policy links","The source can change Group Policy links on the target.","A WriteGPLink relationship was recorded.","Changing policy links may change which settings apply to users or computers in scope.","Review policy-link delegation, linked policies, enforcement, filtering and affected objects.","Link-edit rights do not by themselves grant control of a policy or guarantee its application.","Restrict policy-link editing and review the linked policies and affected scope."});
guide.Add("SQLAdmin",new string[]{"Database administration","The dataset represents administrative rights on a SQL Server target.","An imported or collected SQLAdmin relationship was present.","Administrative database access may expose data and sensitive service configuration.","Validate the SQL role, business owner, service identity and least-privilege configuration.","The relationship does not prove operating-system administration or successful connection.","Reduce unnecessary SQL administrative privileges and review the database service identity."});
guide.Add("MemberOf",new string[]{"Group membership","The source is a member of the target group.","Direct or primary group membership was recorded.","The source may receive permissions assigned to this group. Membership is normal directory behavior.","Check whether membership is intended and whether the group grants sensitive access.","Nested groups and token behavior affect effective access. This is context, not a vulnerability by itself.","If this membership is unnecessary, remove the source from the target group after checking dependent access."});
guide.Add("Contains",new string[]{"Directory location","The source container contains the target object.","The directory object’s parent was recorded.","Location helps explain policy and inherited permissions.","Review the organizational structure and inheritance when investigating another permission.","Containment alone does not grant control.","Review the organizational structure and inheritance when investigating another permission."});
guide.Add("GPLink",new string[]{"Group Policy link","The policy is linked to the target site, domain or organizational unit.","An enabled Group Policy link was recorded.","The policy may affect objects in its scope.","Review security filtering, inheritance, enforcement and policy settings.","A link alone does not prove that every object receives the policy.","Review security filtering, inheritance, enforcement and policy settings."});
guide.Add("Enroll",new string[]{"Certificate enrollment permission","The source has a recorded enrollment or auto-enrollment permission on the certificate object.","A selected enrollment right was read from the certificate object ACL.","Enrollment rights are normal in PKI. Risk depends on the template, authority and issuance controls together.","Review template flags, EKUs, approvals, authorized signatures and publication on an authority.","BHTest records enrollment facts; this is not a derived AD CS escalation finding.","Review template flags, EKUs, approvals, authorized signatures and publication on an authority."});
guide.Add("AutoEnroll",new string[]{"Certificate enrollment permission","The source has a recorded enrollment or auto-enrollment permission on the certificate object.","A selected enrollment right was read from the certificate object ACL.","Enrollment rights are normal in PKI. Risk depends on the template, authority and issuance controls together.","Review template flags, EKUs, approvals, authorized signatures and publication on an authority.","BHTest records enrollment facts; this is not a derived AD CS escalation finding.","Review template flags, EKUs, approvals, authorized signatures and publication on an authority."});
guide.Add("PublishedTo",new string[]{"Template publication","The certificate template is published on the target certificate authority.","The authority’s certificateTemplates list referenced this template.","Publication helps establish where a template can be requested.","Review the template alongside the authority’s issuance and enrollment controls.","Publication alone does not establish an unsafe certificate configuration.","Review the template alongside the authority’s issuance and enrollment controls."});
guide.Add("TrustRelationship",new string[]{"Domain trust inventory","The collected domain has a recorded trust relationship with the remote domain.","A trustedDomain object was found in the directory.","Trust configuration affects cross-domain authentication boundaries.","Review direction, attributes, SID filtering, selective authentication and the business purpose.","This inventory link does not describe attack direction or prove cross-domain escalation.","Review direction, attributes, SID filtering, selective authentication and the business purpose."});
            return guide;
        }
        [STAThread]
        public static void Run(string indexPath)
        {
            Application.EnableVisualStyles();
            using(var window=new DesktopWindow(indexPath))window.ShowDialog();
        }
        internal static Dictionary<string,object> Map(object value){return (Dictionary<string,object>)value;}
        internal static string Text(Dictionary<string,object> row,string key){object value;return row.TryGetValue(key,out value)?Convert.ToString(value,CultureInfo.InvariantCulture):"";}
        internal static long Number(Dictionary<string,object> row,string key){return Convert.ToInt64(row[key],CultureInfo.InvariantCulture);}
        internal static bool Flag(Dictionary<string,object> row,string key){return row.ContainsKey(key)&&Convert.ToBoolean(row[key],CultureInfo.InvariantCulture);}
        internal static List<object> Rows(Dictionary<string,object> row){return (List<object>)row["Rows"];}
        internal static string ChangeProcess="Before changing it: Confirm the business owner and dependent services. Save the exact current ACL, membership or delegation, including inheritance.\r\n\r\nValidation: Rescan the same scope with comparable permissions and endpoint coverage. Check this chain and alternative paths, and test legitimate service/support workflows.\r\n\r\nRollback: Restore only the documented original setting through the approved change process if required access breaks. Reassess narrower delegation.";
        internal static string Explain(Dictionary<string,object> edge)
        {
            string type=Text(edge,"ty");string[] h;
            if(!Guide.TryGetValue(type,out h))h=new string[]{type,"A recorded relationship in the supplied index.","The dataset contains this relationship.","Its effect depends on the object types and source data.","Verify the relationship's source documentation and prerequisites.","Do not assume that an unfamiliar relationship establishes effective access.","Inspect the original evidence before choosing a change."};
            return h[0]+"\r\n"+Text(edge,"sn")+" → "+Text(edge,"tn")+"\r\n"+type+"\r\n\r\nWhat this means\r\n"+h[1]+"\r\n\r\nWhy it is shown\r\n"+h[2]+"\r\n\r\nPossible impact\r\n"+h[3]+"\r\n\r\nWhat to verify\r\n"+h[4]+"\r\n\r\nLimits\r\n"+h[5]+"\r\n\r\nRecommended change to review\r\n"+h[6]+"\r\n\r\n"+ChangeProcess;
        }
    }

